from assemble_topic import assemble, W, read, dump, stamp
FACTS={
'01':('Falling mortality with continued high fertility can widen natural increase during demographic transition.','Global migration redistributes people but does not directly increase the world population total.'),
'02':('Total population change combines births minus deaths with arrivals minus departures across the stated boundary.','Natural change and net migration are separate components that can reinforce or offset one another.'),
'02-01':('Crude birth rate expresses live births per 1,000 population over the stated year using a suitable denominator.','Birth counts and birth rates can rank populations differently because denominators differ.'),
'02-02':('Crude death rate expresses deaths per 1,000 population over the stated year.','Age composition affects crude mortality comparisons alongside survival conditions.'),
'02-03':('Internal migration changes national distribution while international net migration can change the national total.','Zero net migration can coexist with substantial arrivals and departures.'),
'03':('Population pressure depends on resources, productive capacity, technology and access rather than density alone.','Population and available support can change independently or together.'),
'03-01':('Overpopulation concerns pressure beyond the available sustainable support under the stated conditions.','A large population or high density alone does not prove a resource or access deficit.'),
'03-02':('Underpopulation concerns insufficient people or relevant capacity to use available opportunities effectively.','Low density alone does not establish feasible unused production or a need for more settlement.'),
'04':('Social, economic, health, policy and movement conditions influence demographic components.','A policy’s intention, delivery and measured demographic outcome are different kinds of evidence.'),
'04-01':('Education, childbearing timing and access to voluntary services can influence fertility decisions.','A national rate does not establish identical choices or circumstances across households.'),
'04-02':('Childcare, housing, livelihood security and the opportunity cost of time can affect desired or realised childbearing.','Economic influences depend on context rather than a uniform response by every household.'),
'04-03':('China’s stated July 2021 policy direction allowed three children with supporting measures intended to encourage births.','Japan’s 2025 white paper describes a December 2024 childcare-support direction rather than a demonstrated fertility outcome.'),
'04-04':('Suitable water, sanitation, nutrition, prevention and healthcare can improve survival through specific pathways.','A healthcare building alone does not establish usable staff, supplies or timely access.'),
'04-05':('Conflict, unsafe living conditions and environmental hazards can affect mortality through exposure and service disruption.','A crude death-rate difference alone does not establish a difference in healthcare quality.'),
'05':('Consequences of change depend on age structure, economic opportunity, services and resource distribution.','Young and ageing structures can create different service needs despite equal total dependency ratios.'),
'05-01':('The common teaching age bands are under fifteen, fifteen to sixty-four and sixty-five or more, unless a resource specifies otherwise.','Age-defined working groups are not a literal count of employed or earning people.'),
'05-02':('Age dependency ratio divides the specified dependent groups by working ages and multiplies by 100.','Its denominator is working-age population, not all residents or the number currently employed.'),
'05-03':('Standard of living concerns material conditions and usable services, with distribution relevant to interpretation.','Average income or output does not describe every household’s welfare.'),
'05-04':('Life expectancy at birth summarises expected years under a continuing age-specific mortality schedule.','It is not an individual prediction or simply a small sample’s average age at death.'),
'05-05':('Infant mortality concerns deaths before age one per 1,000 live births or the corresponding estimated probability.','Under-five deaths and total population are not the age limit and denominator for infant mortality.'),
'06':('The four-stage DTM represents a broad change from high to low birth and death rates and consequent natural change.','A population total accumulates past changes and can keep rising as its growth rate falls.'),
'06-01':('Stage one combines high births and deaths with a small variable average natural-change gap.','High births alone do not establish rapid growth when deaths are also high.'),
'06-02':('Stage two combines high births with falling deaths and a widening natural-growth gap.','Rapid natural growth can arise from falling deaths without rising births.'),
'06-03':('Stage three has falling births and relatively low deaths, narrowing positive natural increase.','Slower natural growth can coexist with a continuing increase in total population.'),
'06-04':('Stage four has low birth and death rates with a small natural-change gap.','Low rates do not mean no births or deaths, and migration can alter the national change.'),
'07':('Age-sex pyramids show age structure using specified counts or percentage denominators.','Bulges, gaps and sex differences require contextual evidence rather than a single universal explanation.'),
'08':('Pyramid shapes can be linked conditionally to demographic transition and accumulated cohort history.','Equal dependency ratios can conceal different young and older shares or migration histories.'),
'09':('Density is population divided by matching area, while distribution describes spatial arrangement.','A regional average does not mean uniform settlement within its boundary.'),
'09-01':('Water, climate, relief and soils can influence settlement through resources and practical constraints.','Physical conditions interact with technology and other human factors rather than determining one inevitable pattern.'),
'09-02':('Employment, markets and transport can support population concentration through livelihood opportunities.','An economic attraction does not establish that every migrant obtains work.'),
'09-03':('History, land allocation, policy, services and networks influence settlement patterns.','Changing administrative boundaries or definitions can affect comparisons of growth and density.'),
'10':('Migration requires a change of usual residence under the stated rule and can cross internal or international boundaries.','Push and pull influences explain pressures and perceived opportunities, not guaranteed outcomes.'),
'10-01':('Rural–urban migration is an internal residential move when both places are in the same country.','Internal movements alter local totals but cancel across the unchanged national boundary.'),
'10-02':('Voluntary international moves can involve work, education or family opportunities across a national border.','Origin and destination can experience simultaneous benefits and costs from the same movement.'),
'10-03':('Forced movement can follow danger or compulsion and need not cross a national border.','Boundary and circumstances must be known before assigning movement categories or precise legal status.'),
'11':('Population growth can raise aggregate demand even if some per-person use falls.','Environmental outcomes also depend on consumption, infrastructure, production and management.'),
'12':('Appropriate strategies connect voluntary choice, usable services, economic opportunities and ecological limits.','Population targets or announcements alone do not establish welfare or environmental outcomes.'),
'91':('Population-related environmental assessment requires matched dates, boundaries, definitions and relevant resource observations.','An association of growth and environmental change does not isolate population as the sole cause.'),
'92':('Census figures describe a dated population baseline under stated definitions rather than a permanent present total.','Density choropleths require matching areas, units and a clear non-overlapping key.')}
CARDS={
'001':('Explain how declining deaths can produce rapid population growth while births remain high.','Improved survival reduces deaths while births continue adding people. The positive birth–death gap widens and accumulates into a larger total. The mechanism does not require the birth rate itself to rise.',['1 mark for declining mortality as a factor; 1 for the high-birth/low-death link; 1 for wider natural increase; 1 for the accumulated-total effect.']),
'002':('Describe the growth comparison: A begins at one million and increases 2%; B begins at ten million and increases 1%, using the stated opening totals.','A adds 20,000 and B 100,000. A has the higher percentage rate but B the larger numerical increase. A lower rate does not by itself mean a declining total.',['1 mark for the paired numerical pattern; 1 for rate/starting-total evidence; 1 for the rate/number interpretation.']),
'003':('Name the population-change balance calculated as births minus deaths.','Natural change or natural increase where positive.',['1 mark for the balance name natural change/increase.']),
'004':('Describe the annual balance: births 3,000, deaths 1,000, arrivals 500, departures 800; other adjustments are absent.','Natural increase is 2,000, net migration minus 300 and total increase 1,700 people. Negative net migration partly offsets natural growth rather than establishing total decline.',['1 mark for the natural-change pattern; 1 for net-migration data; 1 for the reconciled total interpretation.']),
'005':('Name the indicator expressing live births per 1,000 population in a stated year.','Crude birth rate.',['1 mark for the indicator name crude birth rate.']),
'006':('Name the indicator expressing deaths per 1,000 population in a stated year.','Crude death rate.',['1 mark for the indicator name crude death rate.']),
'007':('Name the movement balance obtained from immigration minus emigration at the stated boundary.','Net migration.',['1 mark for the balance name net migration.']),
'008':('Explain why rapid settlement growth can create a water-service gap where supply does not expand and per-person need remains unchanged.','More residents increase total demand. With usable delivery unchanged, demand can exceed capacity. Unmet needs or allocation pressures follow unless suitable supply, loss or demand measures change the balance.',['1 mark for more users as a factor; 1 for the total-demand link; 1 for exceeding fixed capacity; 1 for the conditional access effect.']),
'009':('Describe the resource account: 1,000 residents each need 100 litres daily, while dependable supply is 80,000 litres. Other resources are unmeasured.','Daily need is 100,000 litres and the water gap 20,000. The record supports this service deficit under the stated requirement. It does not establish every dimension of overpopulation or exclude other management responses.',['1 mark for the demand/gap relationship; 1 for the numerical evidence; 1 for the bounded resource interpretation.']),
'010':('Name the population-resource condition where pressure exceeds available sustainable support under the stated circumstances.','Overpopulation.',['1 mark for the condition name overpopulation.']),
'011':('Name the condition where insufficient people or relevant labour capacity limits effective use of feasible resource opportunities.','Underpopulation.',['1 mark for the condition name underpopulation.']),
'012':('Explain how access to voluntary family-planning services can influence population growth where people have unmet needs for control over childbearing.','Usable information and services can help people achieve desired timing or family size. This can reduce unintended births under those conditions, narrowing natural growth relative to a higher-birth alternative. The outcome depends on actual access and choices.',['1 mark for service access as a factor; 1 for the choice/timing link; 1 for the conditional birth change; 1 for its natural-growth effect.']),
'013':('Describe the component contrast per 1,000: A births 30, deaths 10, net migration 0; B births 10, deaths 12, net migration +5.','A has natural and total growth of twenty per 1,000. B has natural decline of two but total growth of three per 1,000. Both totals rise through different balances.',['1 mark for A’s pattern; 1 for B’s component evidence; 1 for the contrasting total-growth interpretation.']),
'014':('Name one social influence on births involving opportunities and timing rather than a fixed biological limit.','Education, later childbearing or access to voluntary family-planning information/services.',['1 mark for a relevant social-influence name.']),
'015':('Name one economic constraint that can affect desired or realised childbearing.','Childcare costs, housing cost, livelihood insecurity or the opportunity cost of time.',['1 mark for a relevant economic-factor name.']),
'016':('Name the birth-policy direction announced by China in July 2021, when permission rose to three children.','A shift towards supporting or encouraging births in response to low fertility/ageing concerns.',['1 mark for the relevant policy-direction point.']),
'017':('Name one public-health improvement that can reduce a specific mortality risk.','Suitable sanitation, safe water, vaccination or accessible appropriate healthcare.',['1 mark for a relevant improvement name.']),
'018':('Name one environmental or social pressure that can increase mortality risk through exposure or disrupted services.','Conflict, unsafe water, severe food insecurity or an appropriately explained hazard.',['1 mark for a relevant pressure name.']),
'019':('Explain why a youthful population can create a future workforce opportunity without already proving higher living standards.','Large young cohorts can later enter working ages. Suitable health, education and jobs are needed to turn that potential into productive livelihoods. Without those conditions, service and employment pressure can remain despite the age-structure opportunity.',['1 mark for cohort size as a factor; 1 for the future-workforce link; 1 for enabling skills/jobs; 1 for the conditional welfare effect.']),
'020':('Describe the service contrast: A’s dependent ages are mostly children, while B’s are mostly older people; their total age dependency ratios are equal.','The total demographic support ratio matches but composition differs. A has stronger child/school-related needs; B may need different older-care, healthcare or accessibility services. Equal ratios do not establish identical costs or contributions.',['1 mark for the equal-total/different-composition pattern; 1 for paired service evidence; 1 for the qualified implications.']),
'021':('Name the common teaching age bands for young, working-age and older groups, unless a resource states others.','Under fifteen; fifteen to sixty-four; sixty-five or more.',['1 mark for the complete age-band point.']),
'022':('Name the denominator in the total age dependency ratio under the usual fifteen-to-sixty-four convention.','Population aged fifteen to sixty-four, not the employed count or total population.',['1 mark for the denominator name/age-band point.']),
'023':('Name the development concept concerning material conditions and usable services such as income, housing and water.','Standard of living.',['1 mark for the concept name standard of living.']),
'024':('Name the indicator summarising expected years at birth under a continuing current mortality schedule.','Life expectancy at birth.',['1 mark for the indicator name life expectancy at birth.']),
'025':('Name the indicator concerning deaths before the first birthday per 1,000 live births or the corresponding estimated probability.','Infant mortality rate.',['1 mark for the indicator name infant mortality rate.']),
'026':('Name the model describing a broad four-stage transition from high birth/death rates to low birth/death rates.','The Demographic Transition Model.',['1 mark for the model name DTM/Demographic Transition Model.']),
'027':('Describe the supplied four-stage rate chart, using births/deaths per 1,000: 40/38, 40/15, 25/10, 11/10.','Natural-change gaps are 2,25,15 and 1 per 1,000. The gap widens as deaths fall, then narrows as births fall. The largest gap is stage two; a population total is a different accumulated measure.',['1 mark for the gap sequence pattern; 1 for the component/chart evidence; 1 for the rate/total distinction.']),
'028':('Describe a stage-one model record with high birth rate 40 and high death rate 38 per 1,000, allowing fluctuations.','Both rates are high and their gap is small at two per 1,000. Natural growth is slow in the stated record despite high births. Fluctuations could alter the short-term gap.',['1 mark for the paired-high pattern; 1 for gap evidence; 1 for the growth interpretation.']),
'029':('Describe a stage-two model record in which births remain high while deaths fall.','The positive natural-change gap widens. Improved survival can increase growth without a birth-rate rise. The total rises as the positive balance accumulates.',['1 mark for the widening-gap pattern; 1 for the birth/death evidence; 1 for the accumulation interpretation.']),
'030':('Describe a stage-three model record with falling births, relatively low deaths and births still above deaths.','The natural-growth gap narrows but remains positive. Population can continue increasing while its growth rate slows. Falling births do not by themselves mean total decline.',['1 mark for the narrowing-positive pattern; 1 for the paired-rate evidence; 1 for the rate/total interpretation.']),
'031':('Describe a stage-four model record with births 11 and deaths 10 per 1,000 and migration unspecified.','Both rates are low, with natural increase of one per 1,000. The gap is small rather than births/deaths ceasing. Total national change still needs the migration balance.',['1 mark for the low-rate pattern; 1 for gap evidence; 1 for the migration/total limitation.']),
'032':('Calculate the young share in this age-sex table: under fifteen males/females 150/150; fifteen–sixty-four 280/320; sixty-five-plus 40/60. All groups exhaust the population.','Young total is 300 and total population 1,000, so the fraction 300/1,000 is 0.3, equivalent to 30%.',['1 mark for the method of summing both young sexes and all groups; 1 for the correct answer 30; 1 for the percent unit with the whole-population denominator.']),
'033':('Describe the supplied age-sex pyramid with five-year male/female counts: 50/50 in each of 0–4,5–9,10–14; 28/32 in each band from 15–19 through 60–64; 10/15 in each of 65–69,70–74,75–79,80-plus. The last band is labelled open-ended.','Working ages are largest at 600, young ages total 300 and older ages 100. Females exceed males in the working and older groups while young counts match. The displayed shape alone does not isolate fertility, survival or migration causes.',['1 mark for the age-size pattern; 1 for the paired sex/age evidence; 1 for the bounded causal interpretation.']),
'034':('Calculate the total age dependency ratio for 300 under fifteen, 600 aged fifteen–sixty-four and 100 sixty-five-plus.','Dependants total 400; 400/600 is about 0.667, giving approximately 66.7 dependants per 100 working-age people.',['1 mark for the dependent-over-working-age method; 1 for the correct rounded answer 66.7; 1 for the ratio unit per 100 working-age people.']),
'035':('Describe the supplied paired population-pyramid panels and their aggregate age table: A has 300 young/600 working-age/100 older; B has 200/600/200 under the same bands. Relate cautiously to demographic history.','Both have 400 dependants and the same total age ratio, but B has a larger older share and smaller young share. This can be consistent with lower recent fertility and longer survival, while migration/history could also contribute. Shape alone does not assign an exact DTM stage.',['1 mark for the equal-ratio/different-share pattern; 1 for paired age evidence; 1 for the qualified model/history interpretation.']),
'036':('Explain how a port or employment centre can support concentrated settlement despite a dry setting where usable water is supplied.','Employment and trade create livelihood opportunities. Suitable water and infrastructure make settlement more feasible despite the physical constraint. People and services can concentrate around those opportunities, though actual growth needs population evidence.',['1 mark for employment/trade as a factor; 1 for the livelihood link; 1 for the enabling water/infrastructure condition; 1 for the conditional concentration effect.']),
'037':('Describe the supplied density map/table: A has 20,000 residents in 1,000 km²; B has 30,000 in 3,000 km². Key: 0–<10, 10–<20, 20+ people/km².','A has density twenty and enters the highest class; B has density ten and enters the middle class. B has the larger total but lower average density. Shading does not imply uniform settlement within either area.',['1 mark for the density/class pattern; 1 for paired population/area evidence; 1 for the average/distribution limitation.']),
'038':('Name one physical influence on population distribution involving usable natural resources or terrain.','Water, climate, relief or suitable soils.',['1 mark for a relevant physical-factor name.']),
'039':('Name one economic influence attracting concentrated settlement.','Employment, markets, transport/trade opportunities or relevant industry/services.',['1 mark for a relevant economic-factor name.']),
'040':('Name one historical or institutional influence on population distribution.','Land allocation, policy, service investment or an appropriately stated settlement history.',['1 mark for a relevant human-factor name.']),
'041':('Explain how limited work at an origin and perceived jobs at a destination can encourage migration without proving every migrant gains work.','The origin condition pushes departure while expected opportunities pull towards the destination. A residential move can follow, but employment depends on actual jobs, skills and access. The motive is not proof of the outcome.',['1 mark for an origin factor; 1 for the push/pull link; 1 for the move mechanism; 1 for the conditional livelihood effect.']),
'042':('Describe the movement balance: a town receives 800 residents and loses 500, while births exceed deaths by 200; other changes are absent.','Net migration adds 300 and natural increase adds 200, giving total growth of 500. Gross movement is 1,300 but is not the migration contribution to net growth.',['1 mark for the net-flow pattern; 1 for component evidence; 1 for the total/gross distinction.']),
'043':('Name a residential move from a rural Namibian area to Windhoek without crossing the national boundary.','Internal rural–urban migration.',['1 mark for the complete movement-category name.']),
'044':('Name a chosen residential move across a national border for a suitable employment opportunity.','Voluntary international migration.',['1 mark for the movement-category name.']),
'045':('Name the broad movement type when people must leave an unsafe origin because of severe danger, without assuming a legal status.','Forced or involuntary migration/displacement.',['1 mark for a relevant movement-type name.']),
'046':('Explain how population growth can increase waste pollution where collection capacity does not expand and per-person waste is unchanged.','More users generate more total waste. Fixed collection capacity can leave additional material uncollected. Unsuitable accumulation can then affect land or water through the relevant pathway unless management changes.',['1 mark for user growth as a factor; 1 for the waste-total link; 1 for collection shortfall; 1 for the conditional pollution effect.']),
'047':('Describe the daily water-demand record: people increase from 1,000 to 1,500 while use falls from 100 to 80 litres per person. Source recovery is unmeasured.','Per-person use falls but total need rises from 100,000 to 120,000 litres daily. The evidence shows an aggregate-demand increase despite efficiency per user. It does not establish depletion without source and withdrawal records.',['1 mark for the opposite rate/total trend pattern; 1 for numerical evidence; 1 for the resource-balance limit.']),
'048':('Name one rights-respecting strategy helping people achieve desired timing or number of children.','Usable voluntary family-planning or reproductive-health services.',['1 mark for a relevant voluntary-service strategy name.']),
'049':('How far do you agree that a published population target alone proves improved living standards and sustainability? Service access, choice, employment and resource outcomes are unrecorded.','Disagree. A target describes intention rather than delivered rights-respecting services or outcomes. Economic opportunities, access and ecological evidence are needed. A changed population rate would also not by itself establish fair welfare or maintained resources.',['Up to 4 C marks for judgement using the target/outcome distinction and relevant missing service/economic/resource evidence.','1 C mark for a supported decision about demonstrated improvement.']),
'050':('Describe a sequence for assessing whether mapped land-cover change accompanies population growth in a settlement.','Define the area, dates and classification; obtain comparable population and land-cover records; compare changes with values and context, then state the supported relationship and limits.',['1 mark for the first boundary/date step; 1 for matched evidence method; 1 for the recorded comparison/result and bounded conclusion.']),
'051':('Explain why changed census boundaries can mislead a before-and-after population/environment comparison.','Different areas contain different people and land, so the apparent change may partly reflect a boundary change. Consistent areas or an explicit adjustment are needed because unmatched totals do not isolate real growth.',['1 mark for the boundary-mismatch reason; 1 for explaining the consistent-area remedy.']),
'052':('Calculate density for a teaching region with 30,000 residents and matching area 3,000 km².','30,000/3,000 = 10 people per square kilometre.',['1 mark for the population-over-area method; 1 for the correct answer 10; 1 for the people/km² unit.']),
'053':('Describe the choropleth classification under this key: 0–<10, 10–<20, 20+ people/km². A is 20 and B 10; internal settlement patterns are not shown.','A occupies the highest class and B the middle class. Exact boundary values each have one category. The shaded regional averages do not establish uniform internal distribution or explain causes.',['1 mark for the paired class pattern; 1 for boundary-value/key evidence; 1 for the within-area/causal limitation.']),
'054':('Explain the error in treating an ageing population’s problems as simply those of too many people overall. What test distinguishes them?','The confusion substitutes total size for age composition. Ageing changes the older share and relevant care/support needs, while resource pressure from total size is a separate issue. Compare age bands and service needs alongside resources to discriminate the two.',['1 mark for the size/structure confusion; 1 for the correct distinction and discriminating age/service test.'])}
TASKS=[
{'objectives':['01','02','06'],'prompt':'(a) Name the balance births minus deaths. [1]\n(b) Describe three stages of demographic transition, linking birth/death patterns to natural change. [3]\n(c) Name the movement balance arrivals minus departures. [1]\n(d) Describe the annual account: births 3,000, deaths 1,000, arrivals 500, departures 800, with other adjustments absent. [2]','answer':'(a) Natural change. (b) Suitable descriptions include stage one high births/deaths with a small gap; stage two high births/falling deaths and a wider gap; stage three falling births/low deaths and narrowing positive gap; stage four low rates and a small gap. Credit three distinct stage descriptions. (c) Net migration. (d) Natural increase is 2,000 and net migration minus 300, producing total growth of 1,700.','guide':['(a) 1 A mark for natural change.','(b) 3 A marks for three distinct stage-pattern point descriptions.','(c) 1 A mark for net migration.','(d) 2 B marks for the two component balances and reconciled total interpretation.'],'split':{'A':5,'B':2},'parts':[('a','Name',1,'A'),('b','Describe',3,'A'),('c','Name',1,'A'),('d','Describe',2,'B')]},
{'objectives':['05','07','08'],'prompt':'Two teaching populations use under-fifteen, fifteen-to-sixty-four and sixty-five-plus groups. A has 300/600/100; B has 200/600/200. The three bands exhaust each population. Employment and income are not supplied.\n(a) Name the age-composition indicator using dependent ages divided by working ages. [1]\n(b) Calculate A’s total age dependency ratio. [2]\n(c) Describe three distinct structural features comparing A and B. [3]\n(d) What judgement is supported about the claim “their working-age totals prove six hundred employed people in each”? [1]','answer':'(a) Age dependency ratio. (b) (300+100)/600 is about 0.667, giving approximately 66.7 dependants per 100 working-age people. (c) Total populations match at 1,000; B has fewer young people and more older people; working-age totals and total dependent totals match despite different composition. Credit three distinct comparative features without double-crediting equivalent expressions. (d) Employment is not established: working age is an age category, not an employed count.','guide':['(a) 1 A mark for age dependency ratio.','(b) 2 B marks for the correct numerator/denominator method and rounded ratio with its per-100-working-age meaning.','(c) 3 B marks for three distinct comparison patterns supported by the resource evidence and values.','(d) 1 C mark for the supported age/employment judgement.'],'split':{'A':1,'B':5,'C':1},'parts':[('a','Name',1,'A'),('b','Calculate',2,'B'),('c','Describe',3,'B'),('d','What',1,'C')]},
{'objectives':['04','05','12'],'prompt':'How far do you agree that China’s stated July 2021 move to allow three children with supporting measures proves births subsequently rose and ageing was resolved? The dated government account describes the policy direction and intended support, but this resource supplies no later fertility, age-structure or implementation results. Judge what the policy evidence establishes. [5]','answer':'Disagree with the outcome claim. The dated account establishes an intended change and support direction, not measured later births or age structure. Costs, choices, access and delivery influence response, while ageing changes over a longer period. Implementation and suitable later demographic records are needed. The policy can have a relevant aim without proving its result or describing today’s complete arrangements.','guide':['Up to 4 C marks for judgement using dated policy evidence, intention/outcome distinction, conditional response and timescale.','1 C mark for a supported decision rejecting demonstrated births/ageing outcomes from the announcement alone.'],'split':{'C':5},'parts':[('a','How far do you agree',5,'C')]}
]
SOURCES=[('NSA-CENSUS-2023','https://nsa.org.na/document/2023-population-and-housing-census-main-report/'),('UN-POPULATION-GROWTH','https://www.un.org/development/desa/pd/sites/www.un.org.development.desa.pd/files/undesa_pd_2022_global_population_growth.pdf'),('UN-WPP-2024','https://www.un.org/development/desa/pd/world-population-prospects-2024'),('WORLD-BANK-DEPENDENCY','https://databank.worldbank.org/metadataglossary/world-development-indicators/series/SP.POP.DPND'),('WHO-INFANT-MORTALITY','https://www.who.int/data/gho/data/indicators/indicator-details/GHO/infant-mortality-rate-%28probability-of-dying-between-birth-and-age-1-per-1000-live-births%29'),('WHO-LIFE-EXPECTANCY','https://www.who.int/data/gho/data/indicators/indicator-details/GHO/life-expectancy'),('CHINA-POLICY-2021','https://english.www.gov.cn/policies/latestreleases/202107/20/content_WS60f6c308c6d0df57f98dd491.html'),('JAPAN-CHILD-SUPPORT-HISTORICAL','https://www.cfa.go.jp/assets/contents/node/basic_page/field_ref_resources/26eaf394-b81d-4778-8303-eeb3d28c89c2/f0af203e/20251021_resources_white-paper_r07_32.pdf')]
if __name__=='__main__':
 assemble('3.1',FACTS,CARDS,TASKS,SOURCES)
 td=W/'topics/3.1';wo=read(td/'work_order.json');p=td/wo['output_files']['learning_items'];d=read(p)
 for i in d['items']:
  if i['item_id']=='ITEM-6137-3.1-035-INTERP':
   i['context']['situation']='VISUAL PENDING: paired-panel variant of VIS-6137-3.1-01; five-year bands and totals specified in notes; requires Claude authoring and independent Codex review.'
   stamp(i,i['claim_ids'])
 dump(p,d)
 n=read(td/'authoring_notes.json');n['visual_reuses']=[{'item_id':'ITEM-6137-3.1-035-INTERP','resource_id':'VIS-6137-3.1-01','requirement':'Two matched five-year age-sex panels as specified in sections 07/08; no unequal-width broad-age substitute.'}];n['source_limits']=['Legacy NSA main-report PDF URL returned 404 and census-atlas endpoint timed out; used live NSA official report landing page for the dated total only, not unviewed detailed tables.','The legacy Japan policy page returned 404; it was replaced with the accessible official 2025 white-paper outline, PDF page 5, describing the December 2024 childcare direction. No later fertility outcome is inferred.'];dump(td/'authoring_notes.json',n)
